import sys

def encode(array, length):
    code = 0
    for i in range(length):
        code = code * 3 + array[i]
    return code

def decode(array, length, code, base):
    for j in range(length - 1, -1, -1):
        array[j] = code % base
        code //= base

def solve():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    m = int(input[1])
    if n < m:
        n, m = m, n
    totalStates = 1
    for _ in range(m):
        totalStates *= 3
    currentDP = [-1] * totalStates
    nextDP = [-1] * totalStates
    stateA = [1] * m
    stateB = [0] * m
    currentDP[encode(stateA, m)] = 0
    for _ in range(n):
        for i in range(totalStates):
            nextDP[i] = -1
        for idx in range(totalStates):
            if currentDP[idx] < 0:
                continue
            decode(stateA, m, idx, 3)
            for mask in range(1 << m):
                decode(stateB, m, mask, 2)
                invalid = False
                for j in range(m):
                    if stateA[j] == 0 and stateB[j] == 0:
                        invalid = True
                        break
                if invalid:
                    continue
                countOnes = 0
                for j in range(m):
                    if stateB[j] == 1:
                        stateB[j] = 2
                        countOnes += 1
                for j in range(m):
                    if stateB[j] == 0 and (stateA[j] == 2 or (j > 0 and stateB[j - 1] == 2) or (j + 1 < m and stateB[j + 1] == 2)):
                        stateB[j] = 1
                newIdx = encode(stateB, m)
                if nextDP[newIdx] < currentDP[idx] + m - countOnes:
                    nextDP[newIdx] = currentDP[idx] + m - countOnes
        currentDP, nextDP = nextDP, currentDP
    maxResult = 0
    for idx in range(totalStates):
        if currentDP[idx] <= maxResult:
            continue
        decode(stateA, m, idx, 3)
        bad = False
        for j in range(m):
            if stateA[j] == 0:
                bad = True
                break
        if not bad:
            maxResult = currentDP[idx]
    print(maxResult)

